let token=localStorage.getItem("basseVendorToken")||"";const $=x=>document.getElementById(x),money=n=>"D"+Number(n||0).toLocaleString();const H=()=>({Authorization:"Bearer "+token});async function api(u,o={}){let r=await fetch(u,{...o,headers:{...H(),...(o.headers||{})}}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Request failed");return d}async function login(){try{let d=await api("/api/vendor/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({whatsapp:$("phone").value,pin:$("pin").value})});token=d.token;localStorage.setItem("basseVendorToken",token);start()}catch(e){alert(e.message)}}function start(){$("login").classList.add("hidden");$("app").classList.remove("hidden");refresh()}function logout(){localStorage.removeItem("basseVendorToken");location.reload()}async function refresh(){try{let [me,st,ps,os]=await Promise.all([api("/api/vendor/me"),api("/api/vendor/stats"),api("/api/vendor/products"),api("/api/vendor/orders")]);$("shop").textContent=me.business_name;$("products").textContent=st.products;$("pending").textContent=st.pendingProducts;$("sales").textContent=money(st.sales);$("earnings").textContent=money(st.earnings);$("productsList").innerHTML=ps.map(p=>`<div class="product-row"><img src="${p.image||""}"><div><b>${esc(p.name)}</b><small>${money(p.price)} · Stock ${p.stock}</small></div><span class="badge">${p.approval_status}</span></div>`).join("")||"<p>No products yet.</p>";$("orders").innerHTML=os.map(o=>`<div class="order-row"><div><b>${esc(o.id)}</b><br><small>${esc(o.product_name)} × ${o.quantity} · ${esc(o.customer_name)}</small></div><b>${money(o.total)}</b><span class="badge">${o.payment_status}</span></div>`).join("")||"<p>No orders yet.</p>"}catch(e){if(e.message.includes("login"))logout()}}function openAdd(){$("modal").classList.remove("hidden");$("form").innerHTML=`<h2>Add Product</h2><form class="form" id="pf"><input name="name" placeholder="Product name" required><select name="category"><option>Fashion</option><option>Electronics</option><option>Phones</option><option>Beauty</option><option>Home & Living</option><option>Accessories</option></select><input name="price" type="number" placeholder="Price" required><input name="stock" type="number" placeholder="Stock" required><input name="images" type="file" accept="image/*" multiple><textarea name="description" placeholder="Description"></textarea><button>SUBMIT FOR APPROVAL</button></form>`;$("pf").onsubmit=submitProduct}async function submitProduct(e){e.preventDefault();try{await api("/api/vendor/products",{method:"POST",body:new FormData(e.target)});$("modal").classList.add("hidden");refresh();alert("Product submitted for Admin approval.")}catch(x){alert(x.message)}}function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}if(token)start();